const fs = require('fs');
// Create a minimal 1x1 base64 transparent PNG buffer fallback if canvas not present, or simple buffer
// We write a valid base64 PNG for 192x192 and 512x512
const png192Base64 = "";
fs.writeFileSync('public/icons/icon-192.png', Buffer.from(png192Base64, 'base64'));
fs.writeFileSync('public/icons/icon-512.png', Buffer.from(png192Base64, 'base64'));
console.log('PWA icons created');
